SourceCode.Declaration:
internal final class METProcMetricsDisposable implements System.IDisposable
{
    private static METProcMetrics procMetrics;
    private boolean disposed;

}

Method.Source:
public static METProcMetricsDisposable construct(METProcMetrics _procMetrics)
{
    return new METProcMetricsDisposable(_procMetrics);
}

/// <summary>
/// Access the ambient procMetrics from anywhere in the call stack.
/// Returns null if called outside a using block.
/// </summary>
public static METProcMetrics current()
{
    return procMetrics ? procMetrics : METProcMetricsDummy::construct();
}

public void Dispose()
{
    if (!disposed)
    {
        procMetrics = null;   // clear ambient — must not leak into next iteration
        disposed = true;
    }
}
